const config = makeConfig({parcel: parcel.origin, freight: freight.origin, directory: 'http://127.0.0.1:1'});
config.connections[0].members.push({account: 'a/b ?한', token: '[REDACTED_SECRET] ?한-sample'});
// Use an ASCII token while retaining a Unicode account in the encoded path.
config.connections[0].members.at(-1).token = '[REDACTED_SECRET]';
const encoded = await startUpstream({name:'encoded', records, rows:[{account:'a/b ?한', path:'/v3/wallets/a%2Fb%20%3F%ED%95%9C/summary', header:'x-member-token', value:'encoded-token', units:3, unit:'credits'}]});
